mapper.select:
select code, coordinates
from pa_addr_info_type


        where code = #{areaCode}


        where parent_code = #{areaCode}


and coordinates is not null
and code not like '3302%'

SELECT IFNULL(n.addrNum, 0) AS childNum, CASE WHEN b.addr_level >= 5 THEN 0 ELSE IFNULL(minimum_grid.minimumNum, 0) END AS minimumNum, b.dept_id, b.id, IF(n.addrNum > 0, true, false) AS isLeaf, b.code, b2.name AS parentName, b.type_code, b.addr_level, b.name, b.parent_code, b.ancestor_codes, b.user_id, b.user_name, b.second_user_id, b.second_user_name, b.rural_grid_type FROM pa_addr_info_type b LEFT JOIN ( SELECT parent_code, type_code, COUNT(1) AS addrNum FROM pa_addr_info_type WHERE type_code = #{typeCode} GROUP BY parent_code, type_code ) n ON n.parent_code = b.code AND n.type_code = b.type_code LEFT JOIN ( SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 3), ',', -1) AS code, 1 AS addr_level, type_code, COUNT(1) AS minimumNum FROM pa_addr_info_type WHERE type_code = #{typeCode} AND addr_level = 5 AND ancestor_codes IS NOT NULL GROUP BY type_code, SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 3), ',', -1) UNION ALL SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 4), ',', -1) AS code, 2 AS addr_level, type_code, COUNT(1) AS minimumNum FROM pa_addr_info_type WHERE type_code = #{typeCode} AND addr_level = 5 AND ancestor_codes IS NOT NULL GROUP BY type_code, SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 4), ',', -1) UNION ALL SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 5), ',', -1) AS code, 3 AS addr_level, type_code, COUNT(1) AS minimumNum FROM pa_addr_info_type WHERE type_code = #{typeCode} AND addr_level = 5 AND ancestor_codes IS NOT NULL GROUP BY type_code, SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 5), ',', -1) UNION ALL SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 6), ',', -1) AS code, 4 AS addr_level, type_code, COUNT(1) AS minimumNum FROM pa_addr_info_type WHERE type_code = #{typeCode} AND addr_level = 5 AND ancestor_codes IS NOT NULL GROUP BY type_code, SUBSTRING_INDEX(SUBSTRING_INDEX(ancestor_codes, ',', 6), ',', -1) ) minimum_grid ON minimum_grid.code = b.code AND minimum_grid.addr_level = b.addr_level AND minimum_grid.type_code = b.type_code LEFT JOIN pa_addr_info_type b2 ON b.parent_code = b2.code
AND b.type_code = #{typeCode}
AND b.parent_code = #{parentCode}
AND b.code = #{code}
AND b.ancestor_codes LIKE #{pattern}

